          document.getElementById("tutorialSkipHint").textContent = persisted ? "\u5DF2\u8BB0\u4F4F\uFF1A\u6B64\u6D4F\u89C8\u5668\u540E\u7EED\u4E0D\u518D\u663E\u793A\u4EFB\u4F55\u6559\u7A0B\u3002" : "\u672C\u6B21\u5DF2\u8DF3\u8FC7\u5168\u90E8\u6559\u7A0B\uFF1B\u6D4F\u89C8\u5668\u672A\u5141\u8BB8\u4FDD\u5B58\u6B64\u504F\u597D\u3002";
          const wasBrief = ZERO.step === 3;
